nextflow_process {

    name "Test process rastair/mbiasparser"
    script "../main.nf"
    process "RASTAIR_MBIASPARSER"

    tag "modules"
    tag "modules_nfcore"
    tag "rastair"
    tag "rastair/mbias"
    tag "rastair/mbiasparser"

    test("sarscov2 paired-end methylated [bam] / sarscov2 genome [fasta]") {

        setup {
            run("RASTAIR_MBIAS") {
                script "../../mbias/main.nf"
                process {
                    """
                    input[0] =  [
                        [ id:'test' ], // meta map
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.methylated.sorted.bam', checkIfExists: true)
                    ]
                    input[1] = [
                        [ id:'test' ], // meta map
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.methylated.sorted.bam.bai', checkIfExists: true)
                    ]
                    input[2] = [
                        [ id:'test' ], // meta map
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                    ]
                    input[3] = [
                        [ id:'test' ], // meta map
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)
                    ]
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = RASTAIR_MBIAS.out.txt
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out, unstableKeys: ['mbias_processed_pdf'])
                    ).match()
                }
            )
        }
    }

    test("sarscov2 paired-end methylated [bam] / sarscov2 genome [fasta] - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.methylated.sorted.bam', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match()}
            )
        }
    }
}

